from pathlib import Path
import json
import os
from html import escape
from urllib.parse import quote

ROOT = Path(__file__).parent
OUT = ROOT / 'dist'
OUT.mkdir(parents=True, exist_ok=True)
ORIGIN = os.environ.get('SITE_ORIGIN', 'https://tk-nexwell.github.io/le-biz-brands').rstrip('/')
EMAIL = 'wholesale@lebizbrands.com'
FAV = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#183f34"/><text x="11" y="46" font-family="Georgia,serif" font-size="43" fill="#e6ee87">lb</text></svg>'
NAV = [('index.html','Home'),('for-brands.html','For brands'),('categories.html','What we buy'),('about.html','Meet Le Biz')]
def brand(): return '<span class="brand-name">le biz<span class="brand-dot">.</span></span><span class="brand-sub">BRANDS</span>'
def button(href,text,style='primary'): return f'<a class="button {style}" href="{href}">{text}</a>'
def img(name,alt,cls='',eager=False): return f'<img class="{cls}" src="assets/{name}.webp" alt="{alt}" width="{1122 if name=="hero-products" else 1536}" height="{1402 if name=="hero-products" else 1024}" loading="{"eager" if eager else "lazy"}" decoding="async">'
def credentials():
 return '<dl class="credentials">'+''.join(f'<div><dt>{a}</dt><dd>{b}</dd></div>' for a,b in [('Florida LLC','Le Biz Brands LLC'),('Federal EIN','Available for onboarding'),('Florida Resale Certificate','Available for onboarding'),('Based in the U.S.','Miami, Florida')])+'</dl>'
def page(file,title,desc,body):
 nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==file else '')+f'>{t}</a>' for p,t in NAV)
 canonical=ORIGIN+('/' if file=='index.html' else '/'+file)
 schema={'@context':'https://schema.org','@type':'Organization','name':'Le Biz Brands LLC','url':ORIGIN,'email':EMAIL,'description':'Miami-based e-commerce retailer working with consumer brands and authorized distributors.'}
 html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#183f34"><title>{escape(title)} | Le Biz Brands</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} | Le Biz Brands"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{canonical}"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,{quote(FAV)}"><link rel="stylesheet" href="assets/styles.css"><script src="assets/site.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="index.html" aria-label="Le Biz Brands home">{brand()}</a><button class="menu-toggle" type="button" aria-controls="main-nav" aria-expanded="false">Menu <span aria-hidden="true">+</span></button><nav id="main-nav" aria-label="Main navigation">{nav}{button('contact.html','Say hello','nav-button')}</nav></div></header><main id="main">{body}</main><footer class="site-footer wrap"><div class="footer-top"><a class="brand" href="index.html" aria-label="Le Biz Brands home">{brand()}</a><p>Miami, Florida.<br>Open to good partnerships.</p><a class="footer-email" href="mailto:{EMAIL}">{EMAIL}</a></div><div class="footer-bottom"><span>© 2026 Le Biz Brands LLC</span><div><a href="for-brands.html">For brands</a><a href="contact.html">Contact</a><a href="privacy.html">Privacy</a></div></div></footer></body></html>'''
 if file == '404.html':
  for path in ['index.html','for-brands.html','categories.html','about.html','contact.html','privacy.html','assets/styles.css','assets/site.js']:
   html=html.replace('href="'+path+'"','href="'+ORIGIN+'/'+path+'"').replace('src="'+path+'"','src="'+ORIGIN+'/'+path+'"')
 (OUT/file).write_text(html)

home = '<section class="home-opening wrap"><div class="opening-title"><p class="eyebrow">Independent retail. Based in Miami.</p><h1>Good products.<br>Let’s <em>talk.</em></h1></div><div class="opening-intro"><p>We’re Le Biz Brands. We buy from consumer brands and authorized distributors to bring everyday products to the U.S. online market.</p>'+button('for-brands.html','Let’s work together')+'<a class="quiet-link" href="#hello">A little about us</a></div></section><section class="home-photo wrap"><div class="photo-frame">'+img('everyday-essentials','A sunlit arrangement of family and household essentials',eager=True)+'<div class="photo-label"><span>At home in the everyday.</span><span>le biz.</span></div></div><p class="photo-caption">Baby &amp; family · Personal care · Home &amp; lifestyle · Toys</p></section><section class="home-story wrap" id="hello"><p class="eyebrow" data-reveal>Hello from Le Biz</p><div data-reveal><h2>You’ve put care into your products.<br><em>We think that matters.</em></h2><div class="story-copy"><p>We’re building a retail business around products people use, enjoy and come back for. And we want to get to know the people behind them.</p><p>For us, a good supplier relationship starts with an honest conversation: what you sell, where it can be sold, and how we can work together.</p><a class="inline-link" href="about.html">Meet Le Biz</a></div></div></section><section class="home-interests"><div class="wrap interest-layout"><div data-reveal><p class="eyebrow">What catches our eye</p><h2>For the bath.<br>The playroom.<br><em>The everyday.</em></h2><p>Our purchasing interests start here.</p></div><div class="category-links" data-reveal><a href="categories.html#baby"><h3>Baby &amp; Family</h3><span>Care for the little ones</span></a><a href="categories.html#care"><h3>Personal Care</h3><span>The daily routine</span></a><a href="categories.html#home"><h3>Home &amp; Lifestyle</h3><span>Useful things for home</span></a><a href="categories.html#toys"><h3>Toys</h3><span>A little room for play</span></a></div></div></section><section class="home-note wrap" data-reveal><p class="eyebrow">A note for suppliers</p><h2>Let’s start with<br>what you’re working on.</h2><p>Have a wholesale range you’d like us to see?<br>Cristina is the person to speak to.</p>'+button('contact.html','Introduce your business')+'</section>'
page('index.html','Good products. Let’s talk.','Le Biz Brands is an independent Miami-based e-commerce retailer. We buy from consumer brands and authorized distributors for the U.S. online market.',home)

faq_items=[('Who do you buy from?','Consumer brands and authorized distributors. We’ll ask about your range, sourcing documentation and wholesale terms so we can understand the opportunity.'),('Where do you sell?','Our focus is leading U.S. online marketplaces, including Amazon where supplier permissions and marketplace requirements allow. We discuss intended sales channels before purchasing.'),('What about order sizes and payment terms?','We agree on quantities, payment terms, lead times and delivery arrangements for each opportunity. Tell us how you usually work when you get in touch.'),('Can you share your business documents?','Yes. Le Biz Brands LLC is a Florida LLC with a federal EIN and Florida Resale Certificate. Cristina can share the relevant documents during supplier onboarding.'),('Is this a product catalog?','No. This site introduces our business and what we’re interested in buying. The unbranded product images are illustrative; they don’t represent current inventory or brand partnerships.')]
faq='<div class="faq-list">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faq_items)+'</div>'
brands='<section class="brand-opening wrap"><p class="eyebrow">For brands &amp; authorized distributors</p><h1>Your products.<br><em>In good company.</em></h1><p class="lead">You know your brand best. We start by listening.</p></section><section class="brand-conversation wrap"><div class="brand-photo" data-reveal>'+img('hero-products','Unbranded personal care products in deep green and cream')+'</div><div class="brand-copy" data-reveal><h2>Let’s get the<br>important things right.</h2><p>Where should your products be sold? How should they be presented? What does a good retail relationship look like to you?</p><p>Those questions come before an order. We buy through authorized sources, discuss pricing and channel requirements, and take care with the product information customers see.</p><p>We’re interested in relationships that can grow through repeat purchasing and regular contact.</p><a class="inline-link" href="contact.html">Talk to Cristina</a></div></section><section class="buying-section wrap" id="process"><div class="buying-intro"><p class="eyebrow">From hello to reorder</p><h2>Here’s how<br>we work.</h2><p>Nothing complicated.<br>Just a clear conversation at each stage.</p></div><div class="buying-story">'+''.join(f'<article data-reveal><h3>{t}</h3><p>{d}</p></article>' for t,d in [('Select','We get to know your range, wholesale offer and permitted sales channels, and look at where there’s a fit.'),('Purchase','We agree on quantities, prices, payment terms and delivery details before placing an order.'),('Fulfill','We coordinate preparation and fulfillment for the products and channels we’ve agreed on, with accurate product information.'),('Reorder','We review replenishment opportunities and keep in touch as the relationship develops.')])+'</div></section><section class="supplier-note wrap" data-reveal><p class="eyebrow">For your first email</p><h2>A catalog is a<br>good place to start.</h2><p>Send us your company website, product range and wholesale price list. Include order minimums, lead times, permitted channels and any brand guidelines you’d like us to know about.</p>'+button('contact.html','Put an introduction together','light')+'</section><section class="faq-section wrap"><div><p class="eyebrow">A few questions you might have</p><h2>Before we talk.</h2></div>'+faq+'</section>'
page('for-brands.html','For brand partners','How Le Biz Brands buys from brands and authorized distributors, from a first conversation to purchasing and replenishment.',brands)

categories=[('baby','Baby & Family','For the little ones.','Everyday products for babies, parents and family life. Think family essentials, care accessories and products that make a daily routine easier.','baby'),('care','Personal Care','Part of the daily routine.','Body and hair care, grooming and useful beauty accessories. Products people can make part of their everyday lives.','care'),('home','Home & Lifestyle','A useful place in the home.','Household essentials, organization and lifestyle accessories. We’re interested in practical products with clear information and a good fit for online retail.','home'),('toys','Toys','Time for a little play.','Creative play, learning and family activities. When you introduce a range, please include age guidance and the relevant product documentation.','toys')]
catbody='<section class="category-opening wrap"><p class="eyebrow">What we’re interested in buying</p><h1>At home in<br><em>the everyday.</em></h1><p class="lead">From family routines to a little downtime. These are the categories we’re getting to know.</p><nav class="category-jump" aria-label="Jump to category">'+''.join(f'<a href="#{key}">{name}</a>' for key,name,headline,desc,param in categories)+'</nav></section><div class="category-cover wrap">'+img('everyday-essentials','Illustrative family, personal care and home essentials in warm daylight',eager=True)+'<p class="photo-caption">A sense of what we’re looking for. Not a live product catalog.</p></div><section class="category-editorial wrap">'+''.join(f'<article id="{key}" class="category-detail" data-reveal><p class="eyebrow">{name}</p><div><h2>{headline}</h2><p>{desc}</p><a class="inline-link" href="contact.html?category={param}">Talk to us about {name.lower()}</a></div></article>' for key,name,headline,desc,param in categories)+'</section><section class="category-outro wrap" data-reveal><h2>Something else?</h2><p>If your products sit outside these categories, we’re happy to take a look.</p>'+button('contact.html?category=other','Tell us about your range')+'</section>'
page('categories.html','What we buy','Our purchasing interests: Baby & Family, Personal Care, Home & Lifestyle, and Toys. Introduce your wholesale range to Le Biz Brands.',catbody)

about='<section class="about-opening wrap"><div><p class="eyebrow">A little about us</p><h1>Small business.<br><em>Personal approach.</em></h1></div><p class="about-location">Hello from<br><span>Miami.</span></p></section><section class="about-letter wrap" data-reveal><p class="eyebrow">Le Biz Brands LLC</p><div><p class="letter-lead">We’re building an e-commerce retail business with good supplier relationships at its heart.</p><p>Le Biz Brands buys consumer products from brands and authorized distributors for sale across leading U.S. online marketplaces. We’re based in Miami, with purchasing interests in baby and family, personal care, home and lifestyle, and toys.</p><p>We’re at the beginning of our journey, and we’re taking the time to get the foundations right: understanding the products, agreeing on where and how they can be sold, and being straightforward with the people we buy from.</p><p>If that sounds like the way you work, we’d like to meet you.</p></div></section><section class="cristina-section"><div class="wrap cristina-layout"><div data-reveal><p class="eyebrow">Your point of contact</p><h2>Say hello<br>to Cristina.</h2></div><div class="cristina-details" data-reveal><h3>Cristina Lopez</h3><p>Director, Purchasing &amp; Wholesale<br>Le Biz Brands LLC</p><p>For product introductions, wholesale opportunities and supplier onboarding, you can reach Cristina directly.</p><a class="inline-link" href="mailto:wholesale@lebizbrands.com">wholesale@lebizbrands.com</a></div></div></section><section class="about-credentials wrap"><div><p class="eyebrow">The business details</p><h2>Ready for introductions.</h2><p>Relevant documents are available directly during supplier onboarding.</p></div>'+credentials()+'</section>'
page('about.html','Meet Le Biz','Meet Le Biz Brands LLC, an independent Miami-based retailer, and Cristina Lopez, Director, Purchasing & Wholesale.',about)

contact='''<section class="contact-page wrap"><div class="contact-intro"><p class="eyebrow">Say hello</p><h1>Have something<br>in mind?</h1><p class="lead">We’d love to hear about your products.</p><p>Send Cristina a note, or use the form to put an introduction together. Catalogs and wholesale price lists are always a useful place to start.</p><div class="direct-contact"><h2>Cristina Lopez</h2><p>Director, Purchasing &amp; Wholesale<br>Le Biz Brands LLC</p><a href="mailto:wholesale@lebizbrands.com">wholesale@lebizbrands.com</a><p class="location">Miami, Florida · United States</p></div><div class="contact-tip"><p class="eyebrow">What to include</p><p>Include your wholesale range, minimum order requirements and permitted sales channels. You can attach catalogs and price lists in your email.</p></div></div><div class="inquiry-card"><p class="eyebrow">Over to you</p><h2>Introduce your business.</h2><form id="inquiry-form"><div class="field-row"><label>Your name<input name="name" autocomplete="name" required maxlength="120" placeholder="First and last name"></label><label>Business email<input name="email" type="email" autocomplete="email" required maxlength="200" placeholder="you@company.com"></label></div><label>Company<input name="company" autocomplete="organization" required maxlength="160" placeholder="Business name"></label><label>Company website <span class="optional">(optional)</span><input name="website" type="url" autocomplete="url" maxlength="250" placeholder="https://"></label><div class="field-row"><label>You represent<select name="relationship" required><option value="">Please select</option><option>Brand</option><option>Authorized distributor</option><option>Other business</option></select></label><label>Category of interest<select name="category" required><option value="">Please select</option><option value="baby">Baby &amp; Family</option><option value="care">Personal Care</option><option value="home">Home &amp; Lifestyle</option><option value="toys">Toys</option><option value="other">Other / Multiple</option></select></label></div><label>Your introduction<textarea name="message" rows="5" required maxlength="3500" placeholder="Tell us about your products, wholesale terms and permitted sales channels."></textarea></label><p class="form-note">Review your message in your email app and add any attachments before sending. The form itself doesn’t send or save your details.</p><button class="button primary form-submit" type="submit">Prepare email</button><p class="form-note">We’ll use the details you send to respond to your inquiry. <a href="privacy.html">Privacy notice</a></p></form><div id="email-ready" class="email-ready" hidden><h3>Your introduction is ready.</h3><p>Open it in your email app, then review and send. If your email app does not open, copy the message and email it to <a href="mailto:wholesale@lebizbrands.com">wholesale@lebizbrands.com</a>.</p><a id="open-email" class="button primary" href="mailto:wholesale@lebizbrands.com">Open email app</a><button id="copy-email" class="button outline" type="button">Copy message</button><textarea id="email-preview" aria-label="Prepared email message" readonly rows="10"></textarea><button id="edit-inquiry" class="inline-link" type="button">Edit introduction</button><p id="copy-status" role="status"></p></div></div></section>'''
page('contact.html','Contact & wholesale inquiries','Contact Cristina Lopez, Director, Purchasing & Wholesale, at wholesale@lebizbrands.com to discuss a brand or distributor opportunity.',contact)
privacy='''<section class="page-hero wrap narrow"><p class="eyebrow">PRIVACY</p><h1>Your information.</h1><p class="lead">Privacy notice · October 1, 2026</p></section><section class="legal-copy wrap narrow"><h2>Who we are</h2><p>This website introduces Le Biz Brands LLC, based in Miami, Florida. Questions about this notice can be sent to <a href="mailto:wholesale@lebizbrands.com">wholesale@lebizbrands.com</a>.</p><h2>Wholesale inquiries</h2><p>The contact form prepares a message in your browser. It does not transmit the form fields to us or save them in browser storage. If you choose to send the message using your email app, we receive the information you include, such as your name, business contact details and product introduction.</p><h2>How we use information</h2><p>We use information you send to respond to inquiries, assess potential supplier relationships and manage business communications. Please do not send sensitive personal information or banking details in an initial inquiry.</p><h2>Website technology</h2><p>We have not added advertising trackers or analytics to this website. The website host and your email provider may process technical information needed to deliver their services, including connection and security logs.</p><h2>Retention and requests</h2><p>We keep business correspondence as needed for the relationship and applicable recordkeeping requirements. Contact us to request access, correction or deletion of information you have provided, subject to any retention obligations.</p><h2>Product imagery</h2><p>Unbranded product imagery is illustrative. It does not identify current suppliers, endorsements or products offered for sale.</p></section>'''
page('privacy.html','Privacy','How Le Biz Brands handles wholesale inquiries and information provided through business communications.',privacy)
page('404.html','Page not found','Find your way back to Le Biz Brands.','<section class="page-hero wrap"><p class="eyebrow">404 / PAGE NOT FOUND</p><h1>Let’s get you<br>back home.</h1><p class="lead">The page you’re looking for isn’t here.</p>'+button('index.html','Back to Le Biz')+'</section>')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+('/' if n=='index.html' else '/'+n)+'</loc></url>' for n in ['index.html','for-brands.html','categories.html','about.html','contact.html','privacy.html'])+'</urlset>')
(OUT/'.nojekyll').touch()
print('Generated 7 pages, sitemap and robots.txt')
